python3 -c '
# Let us check the IIA (Index Industry Association) website directly or search for their site
import urllib.request
import re

url = "https://indexindustry.org/"
req = urllib.request.Request(
    url,
    headers={"User-Agent": "Mozilla/5.0"}
)
try:
    with urllib.request.urlopen(req) as response:
        html = response.read().decode("utf-8")
        # find any links to white papers or news
        links = re.findall(r"href=\"([^\"]+)\"", html)
        for link in links:
            if "digital" in link.lower() or "paper" in link.lower() or "2026" in link.lower():
                print(link)
except Exception as e:
    print("Error:", e)
'

